:root {
  --ink: #26332f;
  --muted: #68746d;
  --paper: #fffdf7;
  --line: #d8ddd3;
  --sage: #dce9dc;
  --forest: #35634b;
  --amber: #d79535;
  --cream: #f4eddc;
}

.climate-card {
  box-sizing: border-box;
  width: 480px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.climate-card header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding-bottom: 13px;
  border-bottom: 1px solid var(--line);
}

.seal {
  display: grid;
  width: 37px;
  height: 37px;
  place-items: center;
  border-radius: 50%;
  background: var(--forest);
  color: var(--paper);
  font-size: 24px;
  line-height: 1;
}

.title-block {
  flex: 1;
}

.eyebrow,
.timestamp {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .08em;
}

.title-block h2 {
  margin: 2px 0;
  font-size: 19px;
  line-height: 1.15;
}

.state {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--sage);
  color: var(--forest);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .07em;
}

.reading-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
  padding: 14px 0;
}

.reading {
  padding: 9px;
  border-radius: 9px;
  background: var(--cream);
}

.reading-label {
  display: block;
  margin-bottom: 4px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.reading strong {
  display: block;
  margin-bottom: 8px;
  font-size: 17px;
  line-height: 1;
}

.meter {
  display: block;
  height: 4px;
  overflow: hidden;
  border-radius: 99px;
  background: var(--line);
}

.fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--forest);
}

.temp-fill { width: 72%; }
.humid-fill { width: 58%; }
.light-fill { width: 18%; background: var(--amber); }

.advisory {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 10px;
  border: 1px solid var(--sage);
  border-radius: 8px;
  background: var(--paper);
}

.advisory-mark {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  border-radius: 50%;
  background: var(--forest);
  color: var(--paper);
  font-size: 11px;
  font-weight: 800;
}

.advisory p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.3;
}

.climate-card footer {
  display: flex;
  align-items: center;
  gap: 7px;
  padding-top: 12px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .06em;
}

.footer-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--amber);
}
